waves.frame_eqs_eel:
rotx = rotx+bass;
roty = roty+mid;
rotz = rotz+treb;
//rotx = 0;
//roty =0;
//rotz = 0;

//convert rotation values from degrees to radians
t1= t8*rotx/180;
t2 = t8*roty/180;
t3 = t8*rotz/180;

t4 = 3*sin(time+0.66*t8);
t5 = 10+8*cos(time+0.66*t8);

waves.point_eqs_eel:
//Define 3D Shape

//Sphere
fvar = sample*512;
svar = fvar*128;
tvar = 0&svar;
nsample = tvar*4.5;
x1 = -.75+(1.5)*sin(sample);
y1 = (1)*cos(t8*nsample);
z1 = (1)*sin(t8*nsample);

//modulate values to adjust for rotation on multiple axes, convert to world co-ordinates
y2 = y1*cos(t1)-z1*sin(t1);
z2 = y1*sin(t1)+z1*cos(t1);
x2 = z2*sin(t2)+x1*cos(t2);
z3 = z2*cos(t2)-x1*sin(t2);
x3 = x2*cos(t3)-y2*sin(t3);
y3 = y2*cos(t3)+x2*sin(t3);
//move resulting shape in 3d space
x4 = x3;
y4 = y3;
z4 = z3+5;
//draw 3d shape in 2d
x=0.5+0.5*(x4/(1+z4*0.5));
y=0.5+0.5*(y4/(1+z4*0.5));

a = -.9+sin(nsample+time);
a = if(below(a,0),0,a);

preset.frame_eqs_eel:
ff = frame/100;
wave_r = sin(5*ff/2)/2+0.5;
wave_g = cos(ff/3)/2+0.5;
wave_b = cos(3*ff/2)/2+0.5;
